module permutation_generator (\n    input [4:0] N, A, B,\n    output reg valid,\n    output reg [4:0] perm [0:15]\n);\n\n    reg [4:0] x, y;\n    reg found;\n    integer i, k;\n\n    always @(*) begin\n        // Step 1: Solve x*A + y*B = N\n        found = 0;\n        y = 0;\n        for (x = 0; x <= 16; x = x + 1) begin\n            if (x * A <= N) begin\n                if ((N - x * A) % B == 0) begin\n                    y = (N - x * A) / B;\n                    found = 1;\n                end\n            end\n        end\n\n        valid = found;\n\n        // Initialize permutation array\n        for (i = 0; i < 16; i = i + 1) begin\n            perm[i] = 0;\n        end\n\n        if (found) begin\n            // Build A cycles\n            for (k = 0; k < x; k = k + 1) begin\n                for (i = 0; i < A; i = i + 1) begin\n                    if (i < A - 1)\n                        perm[k*A + i] = k*A + i + 2;\n                    else\n                        perm[k*A + i] = k*A + 1;\n                end\n            end\n\n            // Build B cycles\n            for (k = 0; k < y; k = k + 1) begin\n                for (i = 0; i < B; i = i + 1) begin\n                    if (i < B - 1)\n                        perm[x*A + k*B + i] = x*A + k*B + i + 2;\n                    else\n                        perm[x*A + k*B + i] = x*A + k*B + 1;\n                end\n            end\n        end else begin\n            // Set -1 (represented as 5'b11111) for invalid case\n            perm[0] = 5'b11111;\n        end\n    end\nendmodule